<div class="page-head"><div><h1>Pacientes</h1></div><form method="get" style="display:flex;gap:8px"><input name="q" value="<?= e($q) ?>" placeholder="Nome, CPF ou telefone" style="padding:8px;border:1px solid var(--sage-line);border-radius:7px"><button class="btn btn-secondary">Buscar</button></form></div>
